import { useState, useHostTheme, useCanvasAction, Stack, Row, H1, H2, H3, Text, Pill, Button, Callout, Divider } from "cursor/canvas";

const brief = {"title":"Farm Dashboard V5: complete compatibility recovery and delivery build order","date":"2026-09-23","mainPath":"C:/Users/Graham/Documents/JoshWalki Farmdash server edit/MAIN CODEBASE/FarmHub/docs/V5-COMPLETE-BUILD-BRIEF-2026-09-23.md","savePath":"C:/Users/Graham/Documents/JoshWalki Farmdash server edit/MAIN CODEBASE/FarmHub/docs/V5-DEMO-SAVE-PREPARATION-AND-ACCEPTANCE-2026-09-23.md","phases":[{"id":"B00","title":"Reconcile the baseline and preserve working changes","legacy":[],"depends":[],"goal":"Begin from Ash's actual partial implementation, not from a speculative rewrite.","steps":["Read the latest handoff, current agent ownership rules and parity checklist before editing. Coordinate shared contracts through the current foundation owner. Do not touch unrelated Realistic-Farming pipeline, mail, watcher or NAS work.","Create an evidence ledger for F01-F14 and B00-B16. Keep separate fields for source change, automated test, packaged artifact, installed behavior and in-game lifecycle. Start unproved fields as NOT TESTED, not PASS.","Reconcile Ash's reported W01 changes: CURRENT_MISSION_START subscription, one update owner, always-visible first update/errors, reset of hasLoaded and corrected readiness clock. Preserve them if correct. Do not reintroduce the unwired onStartMission path.","Reconcile W02 source changes and the reported passing tests. The installed V5 app was explicitly not rebuilt for those changes; record its actual build separately. F13/F14 are additional closure requirements.","Preserve the failing export/config/log and a coherent backup of app configuration, relevant modSettings, demo saves, and the current install/artifact manifest. Record source and destination; backups stay outside watched/export/mod directories.","Choose one controlled test profile and separate userData/port without changing the installed public demo. Verify the current instance identity rather than blindly using historical 8766/8767/8768 assumptions.","Determine the full currently advertised companion set from the catalog, not only the 31 vault recommendations. Every advertised live capability must get an owning adapter and acceptance row; existing supported capabilities cannot silently disappear.","Record current candidate versions without choosing a new marketing version on Graham's behalf. Do not reuse an already published version for different public bytes.","Record filesystem ownership for optional conversion software and installed-app registration as later lifecycle evidence. Do not clean the machine or uninstall shared tools as a planning shortcut."],"tests":["No user save, vault ZIP, public V4 feed, live server selection or unrelated code is changed during baseline collection.","The changed-source identity and installed-build identity are recorded separately.","Every original finding and newly identified test gap has an owner and required evidence."],"output":"Baseline manifest, protected-behavior checklist, scoped backup/restore instructions and phase ledger.","files":["NEW APP/AGENTS.md","NEW APP/PARITY.md","docs/COMPATIBILITY.md","docs/DEMO_COMPANION_MOD_LISTS.md","package.json","FS25_FarmDashboard_App/package.json"]},{"id":"B01","title":"Close the exporter and mission lifecycle incident","legacy":["W00","W01"],"depends":["B00"],"goal":"Prove the actual first-export failure is repaired and remains repaired across save changes.","steps":["Inspect the already changed implementation rather than blindly reapplying W01. Confirm a one-shot subscription is re-armed for every new mission; one-shot on the first save must not mean never subscribed on the second.","Use one engine-supported update path. Test registration counts and dispatch behavior directly rather than suppressing updates with dt heuristics.","Use distinct session tokens for collector work, export jobs and adapter handles. Teardown invalidates every in-flight job before it can commit into the next save.","Clear busy/processing state in protected completion/failure paths. Attribute an exception to its collector without losing independent successful sections.","Record mission start, readiness/defer reason, cycle start, each collector outcome, serialization result and atomic export commit. Errors remain visible with diagnostics off, are deduplicated and redact private data.","Replace the handoff phrase growing data.json with advancing completed generations. Output byte length, nonempty file presence and a first-update log are not completion proof.","Define the first-export deadline from actual grace, configured collection cadence and bounded margin, recording game pause/time-scale and wall-clock observations separately. On failure identify the first missing transition instead of reinstalling the desktop.","Prove cold start, reload, menu-to-another-save, late initialization, interrupted export and the applicable host/client modes. Do not mark the original empty-bootstrap incident closed until a real completed export is captured."],"tests":["L01: Cold load initializes once and advances at least two completed generations.","L02: Same-process save change has a new session identity and no old job commit.","L03: Diagnostics-off collector exception is visible, bounded and does not permanently stall export.","L04: Teardown before completion cannot overwrite a newer session.","L05: Each expected engine update dispatch invokes one coordinator update."],"output":"Exact root cause, lifecycle sequence, source regressions and a captured before/after export/log record.","files":[]},{"id":"B02","title":"Complete safe configuration parsing and domain-aware saves","legacy":["W02"],"depends":["B00"],"goal":"Prevent UI preferences from mutating gameplay collection and prevent damaged files being silently replaced.","steps":["Keep the exact useStateMachine_fields/economy/production=false versus modules=true fixture. Read the actual intended element and exact attribute name, preserving explicit false.","Replace F13's garbage-to-template expectation. A missing file may be initialized; an existing malformed, unreadable or structurally invalid file must fail without a write. Do not treat an I/O error as missing.","Preserve supported unknown attributes/elements and detect duplicate/ambiguous managed structure instead of guessing which modules block wins. Keep reset-to-defaults a separate explicit user action.","Implement per-domain dirty state for appearance/UI, connection/server, mod configuration and access/LAN settings where applicable. Create a no-write assertion on a display-only Save through the real save entry point.","Make the read-modify-write path concurrency-aware using existing file/atomic helpers. Preserve or reject external changes instead of overwriting a newer game-written config with an old UI draft.","Return and display per-domain outcomes. If UI saved but mod write failed, retain mod dirty state, report partial success and permit a scoped retry; do not show a blanket Saved/Synced.","Retain appropriate input validation and bounds without coercing invalid booleans to true. Test denied write, interrupted write and conflict handling.","Remove forced per-load re-enablement only after the parser and migration tests demonstrate safety. Any necessary migration must be versioned, idempotent and preserve deliberate opt-outs."],"tests":["C01: Exact collision fixture passes through production parser.","C02: Display-only save invokes no mod-config writer.","C03: Explicit false, unknown attributes and unrelated XML survive a real save.","C04: Malformed-present file is byte-preserved; missing file initializes.","C05: Partial failure remains visible and only failed domains remain dirty.","C06: Concurrent game edit is preserved or produces a recoverable conflict."],"output":"Safe parser/writer contract, save-domain regression suite and a documented migration decision.","files":["FS25_FarmDashboard_App/tests/modConfigXml.test.js"]},{"id":"B03","title":"Agree additive end-to-end data contracts","legacy":[],"depends":["B01","B02"],"goal":"Make absence, zero, scope and freshness unambiguous before implementing more integrations.","steps":["Add an additive schema/version envelope and section outcome/provenance contract at the existing producer, merger, types and selectors. Do not create a parallel exporter or replace the whole store architecture.","Separate mod detection, adapter support/readiness, read result and freshness. A failed current read may retain last-known data, so one overloaded boolean cannot express the model.","Specify configured source, stable save identity, map identity, session identity, generation, farm and entity keys. Save-slot number alone is insufficient when a career is replaced.","Define full and partial coverage explicitly. A complete known farm with no loans can be zero; a missing unobserved farm cannot borrow an aggregate or silently become zero.","Treat complete empty arrays and explicit disabled modules as authoritative transitions. A read failure is not empty, and a missing current soil measurement is not measured zero.","Standardize canonical units, metric source and calculation basis. Carry real original timestamps; transport arrival time and generation commit time do not update older held measurements.","Define compatibility behavior for older payloads conservatively: unknown completion/freshness stays unknown or labelled last-known. Preserve supported existing views without inventing full completion.","Agree the schema fixture with the shared foundation owner before downstream changes. Implement serializers for nil/null/absent semantics using the existing JSON writer, not invented Lua syntax."],"tests":["D01: Serialize/parse every section state through real producer-compatible fixtures.","D02: Old supported payload remains readable without converting unknown to healthy.","D03: One snapshot can display fresh fleet data and explicitly older held soil data.","D04: Missing farm and valid zero farm cannot produce the same factual result."],"output":"Versioned contract note, representative JSON fixtures and shared normalized types.","files":["FS25_FarmDashboard_Mod/src/FarmDashboardDataCollector.lua","FS25_FarmDashboard_App/dataMerger.js","NEW APP/src/types/dashboard.ts","NEW APP/src/store/dashboard-store.ts"]},{"id":"B04","title":"Resolve active mods, namespaces and independent readers","legacy":["W03"],"depends":["B03"],"goal":"Read only the mods active in this mission through their actual owning APIs.","steps":["Create a mission-scoped registry using the verified game active-mod surface. Use inventory only for metadata after active membership is proven; stale settings files never activate a mod.","Resolve real runtime mod names and supported aliases from the actual package. A ModHub numeric ID or a prefixed vault filename is not a runtime namespace.","Resolve ELS, restrictions, RCC and Imperial symbols from the owning mod environment or verified mission object. Remove unsupported getActiveModByName assumptions; do not flatten globals.","Give each adapter independent capability probing, readiness timeout/retry, error handling and collection cadence. Missing one manager must not hide all companion data.","Cache discovery per mission. Bound retries and entity work; no directory, XML-settings or vault scans per frame.","Make deployment-mode availability explicit. Current-player UI helpers are not a reliable unattended dedicated-server source.","Read game state without buying samples, changing money, setting a recipe, invoking gameplay actions or modifying third-party mods.","Make the registry serve both unit-mode and companion detection so those systems cannot disagree. Invalidate it on teardown and new save identity."],"tests":["A01: All ZIPs installed but unchecked yields base-only dashboard.","A02: Each adapter works with only its genuine prerequisites.","A03: Namespace-faithful fixtures expose correct companion managers.","A04: One adapter throws or initializes late; others and native collectors continue.","A05: Switching from modded save to base save removes previous active presence and units."],"output":"Source-backed registry, adapter interface, version/dependency/mode manifest and isolated reader tests.","files":[]},{"id":"B05","title":"Repair fertiliser, lime and the full soil path","legacy":["W05"],"depends":["B03","B04"],"goal":"Render the correct provider's real field values without guessing from targets, stale snapshots or ownership IDs.","steps":["Trace vanilla fertiliser/lime, PF nitrogen/pH/scan coverage and RF soil measures from the authoritative getter through JSON, XML fallback, merger, normalized selector and all field displays.","Use each provider's documented scale and meaning. Do not reinterpret vanilla application levels as PF physical quantities or a required lime flag as a measured pH value.","Keep current, target, scan availability and freshness independent. A target alone draws no measured-current bar; zero is a valid measured value only when the read succeeded.","Repair F14 by making field fixtures call production xmlCollector and the real merge/selectors. Keep copied toy algorithms out of release evidence.","Use source/save/provider-qualified field identity. Multiple fields on one farmland and map changes must not cross-attach soil readings.","Define metric-level provider selection from actual enabled systems. PF presence alone does not mean every RF capability is unavailable, and a disabled RF soil system cannot override PF.","Preserve existing correct field card text, detail behavior and RF/PF separation. Remove only proven placeholder/coercion bugs.","Show useful unknown reasons such as not sampled, collector starting, unsupported provider or last known. Do not instruct the player to buy another scan when the true issue is failed telemetry."],"tests":["S01: Base fertiliser and lime states match in-game field information.","S02: PF unknown current/known target, measured zero, unknown target and unscanned states differ.","S03: RF authoritative values match their actual scales and source.","S04: Card, detail, overview and relevant map overlay agree.","S05: Multi-field farmland and provider-switch fixtures do not mix values.","S06: Production-path XML fixture proves nested field extraction and downstream rendering."],"output":"Shared soil selectors, source-backed provider mapping, repaired production-path tests and three-provider comparison evidence.","files":[]},{"id":"B06","title":"Make live, held and offline snapshots honest","legacy":["W06"],"depends":["B03","B04","B05"],"goal":"Preserve useful offline history without resurrecting removed data or mixing saves.","steps":["Apply identity validation before bootstrap/minimal-export early exits and before any retained-field enrichment.","Implement one section transition policy used by live hold, last-good update, persistence restore and freshness stamping. Do not fix only the first helper in a chain that later restores old rows.","Complete empty animals/production, zero stock and disabled companions/RF invalidate older current-section backups. Partial or failed reads may retain compatible last-known data with its original provenance.","On a new session of the same persistent save, show old data only as explicit last-known until a new authoritative read. On a different save identity, quarantine it from the selected live view entirely.","Use entity/provider identity, not farmland ID alone, when carrying detail forward. An explicit provider disable invalidates provider-specific enrichment.","Retain existing WebSocket request/generation/server guards; abort or ignore stale responses after rapid selection changes.","Persist section outcomes and timestamps. Migrate old caches as unknown-age last-known rather than deleting all useful history.","Make failure and offline views preserve user context, show last successful sample age and stop claiming Live merely because the socket is connected."],"tests":["R01: Nonempty -> complete empty -> disconnect -> app restart remains empty.","R02: RF/companion enabled -> disabled stays disabled through all backups.","R03: New export with held soil preserves original soil age.","R04: Reused save slot/new career never inherits prior fields, loans or units.","R05: Delayed response from server A cannot populate selected server B.","R06: App restart with game closed displays honest offline data without fresh timestamps."],"output":"Unified transition policy, real ingestion-chain tests and persisted snapshot migration notes.","files":[]},{"id":"B07","title":"Normalize units and effective values exactly once","legacy":["W07"],"depends":["B03","B04","B06"],"goal":"Match supported in-game presentation without altering canonical quantities or double-applying modifiers.","steps":["Read active Imperial/British/Save Unit Profiles settings from source-backed handles and define effective formatter ownership for combinations.","Keep litres, currency, time and other established canonical quantities internally. Convert once at the presentation boundary using shared helpers.","Specify any per-fill-type mass/bushel relationship from the actual provider. Unknown density cannot yield a falsely precise mass conversion.","Distinguish game-current effective prices/rates from base price, estimates and historical realised revenue. Never multiply an already modified price/rate a second time.","Document host versus viewer settings for remote clients. Do not promise client-specific game preferences that are not exported.","Preserve manual UI behavior when no active mod owns presentation. Unit preference saves stay within their settings domain."],"tests":["U01: Inactive Imperial plus leftover config cannot change units.","U02: British-only, Imperial-only, profiles-only and supported combinations match source behavior.","U03: Stock, fleet, recipe and finance views reconcile canonical values.","U04: Liquids, dry crops, mass, zero, unknown and rounding cases are covered.","U05: Provider/save changes clear old unit mode without changing underlying stored data."],"output":"Shared formatters, effective-value ownership policy and same-save numeric comparisons.","files":[]},{"id":"B08","title":"Make companion and core UI truthful, scoped and usable","legacy":["W04"],"depends":["B03","B04","B05","B06","B07"],"goal":"Present meaningful data rather than detection badges or reassuring defaults.","steps":["Use normalized selectors for card/detail/overview values. Keep the existing component library, navigation and visual system; do not redesign working pages.","Show Spreading allowed only after a successful current per-category restriction read. Unknown or stale restriction data cannot be operational advice.","Keep ELS farm rows separate from aggregate totals. A debt-free farm stays zero; an unavailable farm stays unknown. Preserve a valid selected farm even if it owns no fields or vehicles.","Show RCC vanilla region only after an actual successful manager read reports vanilla. Show supported-map crop fallbacks explicitly.","Separate Active / live data, Active / detection only, Starting, Unsupported, Failed and Last known states. Inactive optional mods should not create alarming empty cards.","Provide concise reasons, source/version and last-success age with accessible details. Avoid unbounded Lua stacks or private paths in the normal UI.","Reuse native animal, production, storage and fleet sections. Livestock Monitor, Production Watcher and another dashboard must remain optional enrichments, not prerequisites.","Test keyboard operation, focus after save/errors, accessible state text, narrow windows, long translations, legitimate empty farms and rapid source changes. Use localization keys for every new string.","Preserve known low-fuel filters, bale/storage accounting, per-1000-litre pricing, mileage and existing setup/server workflows as explicit positive regressions."],"tests":["V01: Farm A zero debt does not show farm B totals; explicit aggregate view is labelled.","V02: Valid asset-empty farm selection remains stable.","V03: Missing restrictions/calendar/loans API never renders allowed/vanilla/no loans.","V04: Native views remain useful with every companion disabled.","V05: Keyboard, narrow-window, long-label and error states remain usable."],"output":"Complete UI state coverage and revised support claims backed by actual data capabilities.","files":[]},{"id":"B09","title":"Finish current integrations and correct all catalog claims","legacy":[],"depends":["B04","B08"],"goal":"Complete already advertised integrations before adding more surface area.","steps":["Use the adapter backlog in this brief, plus every existing advertised catalog entry, as the scope ledger. Classify live, limited, detection-only and unsupported honestly.","First close ELS, restrictions, RCC, RealSilo, pallet condition, Advanced Maintenance, seasonal milk, unit settings/profiles and the existing livestock/production integrations.","Replace enabled=true-only placeholders with real source-backed data where live support is promised. Dynamic Market, Soil Work Yield Bonus and all other placeholder entries need explicit implementation scope or truthful detection-only wording.","Correct all ten catalog errors listed in the catalog appendix, including Stall Rental, Animal Food Overview, Production Control, Out Of Fuel and Bushel Plus.","For each adapter pin source version, true runtime ID, supported deployment modes, required dependencies, optional bridges, farm/entity scope, output contract and UI destination.","Use each mod's effective runtime state, not default XML or a description guessed from its name. Verify the RealSilo vault/save version mismatch before choosing reader fields.","Reconcile companion totals with native inventory, finance, production and animals. A companion breakdown enriches a total; it is not a second inventory item.","Complete minimum-set positive, valid-empty, unavailable, error, removal, persistence and two-farm tests before calling an adapter done."],"tests":["I01: Every advertised live card has meaningful positive data evidence.","I02: No enabled-only placeholder is counted as completed live integration.","I03: Every catalog description matches the source-backed meaning.","I04: Core totals do not double-count companion breakdowns.","I05: Current integration coverage includes all advertised entries, not only the sampled vault list."],"output":"Checked-in support manifest, finished priority adapters, corrected catalog and per-adapter evidence bundles.","files":[]},{"id":"B10","title":"Implement useful additional integrations in controlled waves","legacy":[],"depends":["B09"],"goal":"Deliver the worthwhile vault additions without making one optional mod depend on another unnecessarily.","steps":["Wave 1: Seasonal Wool Production, Task List, Production Schedule and Economic History. Keep writes and gameplay control out of scope.","Wave 2: Animal Food Calculator, Animal Planner, Field Profitability Ledger and VIP Order Manager, subject to their actual SP/MP capabilities. Add Factory Profit Calculator coverage from effective recipes where advertised.","Wave 3: Farm Reputation, Yield Tracker, Moisture System, Field Leasing, Rent Your Field, Farmland Marketplace and Distribution Redux after their source/combination gates.","Alternative maintenance systems get separate adapters after the first maintenance contract is stable. Do not require them together or silently replace a working system.","For Silage Compaction Monitor and Farm Operations Dashboard, implement useful native functionality first. Add only unique verified companion data rather than creating a dependency on another UI.","Apply the same per-adapter acceptance contract to every addition. A source-feasible recommendation is not an implemented feature and an upstream multiplayer flag is not live validation.","Do not let a late optional adapter block recovery of native functionality; deliver a candidate with accurate scope when requested. Do not mark the full brief complete until every item is implemented, proven upstream-blocked, or explicitly deferred by Graham.","Do not publish, market or populate a demo card for a future feature merely because a backlog entry exists."],"tests":["N01: Every completed addition passes its minimum supported configuration.","N02: Removing one addition leaves every unrelated adapter and native collector working.","N03: Actual upstream prerequisites are required only for that specific integration.","N04: SP-only and MP-only capabilities cannot be advertised in incompatible deployments."],"output":"Incremental adapter implementations with a complete disposition ledger for all 31 recommendations.","files":[]},{"id":"B11","title":"Prove combinations, transition safety, performance and security","legacy":["W08"],"depends":["B09","B10"],"goal":"Replace pack-level assumptions with evidence over supported configurations and real code paths.","steps":["Generate a versioned minimum-set and constrained-pairwise configuration list from actual dependencies/conflicts. Pairwise coverage is a practical baseline, not mathematical proof of every possible multi-mod combination.","Explicitly exercise high-risk multi-provider stacks: soil/PF, fuel price writers, market/seasonal price models, units/profiles, animal output/consumption, maintenance/fault systems and production distribution/rates.","Test base-only, each supported adapter alone with genuine prerequisites, installed-but-disabled, late/failed readers, removed mod, new save/map and multiple farms.","Test the full production ingestion chain, not duplicate test logic. Include malformed/partial JSON, field-source fixtures, settings no-write, all retention layers and out-of-order responses.","Measure collector duration, full-cycle time, serialization size, repeat error volume, queue depth and renderer update cost. Define a measured budget before declaring an improvement; retain existing frame budget until evidence supports a change.","Use bounded pagination/incremental work where actual entity counts require it. Export coverage/truncation honestly; partial results cannot look like a complete empty farm.","Exercise existing security boundaries with safe fixtures: authorization, read/write separation, path allowlists, untrusted labels, bounded payload sizes and secret redaction. These are acceptance requirements, not claims that every boundary is currently vulnerable.","Run applicable SP, MP host/client and dedicated cases. Respect actual source authority; do not expose another farm's private integration data merely because a global aggregate is accessible.","Run the documented source suites, renderer typecheck, localization checks and focused negative tests; record commands and failures. Do not call skipped or blocked cases passing.","If a previously working behavior fails, stop candidate packaging, record the regression and repair its owning contract before continuing."],"tests":["T01: All F01-F14 regressions exercise real production paths.","T02: Every advertised adapter has minimum-set and absence evidence.","T03: Every permitted pair is covered or listed NOT TESTED; high-risk stacks are explicit.","T04: Before/after measurements and acceptable configured budgets are recorded.","T05: No unsafe data/write surface is introduced by diagnostics or integrations."],"output":"Automated test record, measured performance baseline, supported-combination evidence and precise residual risks.","files":[]},{"id":"B12","title":"Build isolated, read-only website demos","legacy":[],"depends":["B06","B08","B09"],"goal":"Make four reliable interactive examples without exposing the live dashboard's control plane.","steps":["Implement a snapshot data-source mode through the real V5 renderer and existing store/service abstraction. Do not build a separate fake dashboard or duplicate business logic.","Use stable allowlisted demo IDs base, precision-farming, realistic-farming and precision-companions. Each request/context/cache is scoped to demo ID and immutable generation.","Create a sanitized public projection containing only required fields/assets. Remove private player/network identifiers, paths, credentials, arbitrary connection settings and unrelated farms/servers.","Serve static captured demos independently of the live game. Label Recorded demo, capture time, game date/map, provider, enabled capabilities and limitations; an optional live route remains separately labelled.","Enforce read-only at the route/data-source boundary, not only by hiding buttons. Public visitors cannot save settings, change the host's server, install mods, browse arbitrary files, upload or control the game.","Two visitors may select different demos without changing each other or the host. Test rapid switches with delayed requests and unavailable assets.","Publish a validated completed snapshot/assets/manifest set as an immutable generation, then atomically switch its pointer. Keep the previous good generation if validation fails.","Provide feature deep links that select a meaningful populated section. Do not link a advertised loan/compartment/soil feature to an empty detection card.","Maintain current public V4 marketing and release feed boundaries. Separate the new V5 demo work from the existing live tunnel; do not silently reconfigure its passwords or runtime.","Use only permitted assets and link to mod authors rather than redistributing their ZIPs. Downloadable saves need a separate permission/privacy review."],"tests":["WEB01: Two independent visitors remain on distinct demo sources.","WEB02: Mutating/public-path-escape requests are denied; server identity stays unchanged.","WEB03: Snapshot publication rejects bootstrap, missing assets and private data.","WEB04: Recorded timestamps remain recorded after reload and offline use.","WEB05: Feature links work on desktop/mobile and expose actual populated data."],"output":"Four-demo gallery, snapshot manifest/export projection, read-only route tests and a reversible publication process.","files":["Website/demo.html","Website/js/site-config.js","NEW APP/src/platform/DemoBanner.tsx","NEW APP/src/services/api-client.ts","NEW APP/src/services/realtime-connector.ts","NEW APP/src/store/dashboard-store.ts"]},{"id":"B13","title":"Build one coherent V5 candidate","legacy":["W09"],"depends":["B11","B12"],"goal":"Ensure the installed application, renderer and game ZIP come from the same tested source.","steps":["Use the existing agreed output location and V5 packaging scripts. Build mod, UI and app in the established order; never use classic build:all for this candidate.","Keep the mod filename exactly FS25_FarmDashboard.zip. Put versions/build identifiers in metadata and manifests, not a new basename that creates a second game mod.","Create a content/build manifest covering source identity, mod descriptor/runtime version, UI assets, Electron bundle, installer, packaged mod and dependency/converter decisions.","Check actual packaged contents and final hashes. A successful compile or file timestamp does not prove the installed resources include W02 or the corrected adapters.","Close the game before deploying the mod. Preserve any loose developer copy outside the mods search path so release acceptance loads the canonical ZIP once.","Install the exact candidate and identify its launched executable/resources. Do not assume an old install path or a development browser instance is the shipped app.","Do not publish, upload to a server, change an update feed or overwrite public V4 assets as a side effect of building.","Any post-package source fix produces a new identifiable candidate and invalidates affected downstream acceptance evidence; do not silently replace bytes under a passed manifest."],"tests":["PKG01: Source, packaged mod, UI, desktop and installer identities reconcile.","PKG02: Runtime diagnostics show the exact installed candidate and canonical mod.","PKG03: Setup, dashboard and companion routes/assets exist in the packaged app.","PKG04: No release test loads an ambiguous loose+ZIP duplicate."],"output":"One candidate manifest and one clearly identified installer in the existing output location.","files":[]},{"id":"B14","title":"Pass fresh-install, upgrade and installed acceptance","legacy":[],"depends":["B13"],"goal":"Deliver a working application before asking Graham to populate demonstration saves.","steps":["Use a reversible isolated fresh profile or approved backups of all relevant prior app/mod settings. A fresh desktop install that still uses old modSettings is not a fresh setup test.","Keep user save data and unrelated mods intact. Reset only explicitly scoped test state after backup; capture the exact clean boundaries in the evidence record.","Exercise installer, Installed Apps registration, valid uninstaller path, first launch, setup, save selection, dashboard and conversion of a representative map/picture.","If a dependency or ImageMagick remains installed by this candidate, record ownership and intended uninstall behavior. Remove only app-owned installations with safe provenance, never a shared pre-existing copy; test the actual approved design instead of reopening it speculatively.","Exercise per-user installation and any advertised all-user flow, including UAC/error outcomes. Optional conversion failure must not produce a blank dashboard or falsely successful conversion; preserve a working existing fallback.","Uninstall through Windows Installed Apps, confirm expected app-owned cleanup and preservation choices, then reinstall. Separately test an upgrade with existing preferences/offline history and an intentional disabled collector.","Use the exact packaged ZIP/app to compare real data, Settings display-only save, farm/server switches, app restart, game shutdown/offline state and same-process save reload.","Perform the advertised LAN/dedicated route and security checks on the same candidate. If unavailable, keep them NOT TESTED and narrow the release claim rather than treating local SP as equivalent.","Check core protected features: fields, fuel/fleet, animals, production, storage/bales, map images, pricing, mileage and offline history.","Only hand Graham a demo-preparation candidate after this gate passes; include precise launch/save instructions and a visible build ID."],"tests":["INSTALL01: First launch reaches setup and a rendered dashboard, not a blank blue window.","INSTALL02: App appears in Installed Apps and its registered uninstaller works.","INSTALL03: Clean reinstall and existing-user upgrade both work.","INSTALL04: Required image conversion works with accurate optional-dependency outcomes.","INSTALL05: Installed config fix and correct live export are independently evidenced.","INSTALL06: Protected core workflows pass on packaged bytes."],"output":"A demo-preparation-ready candidate, installed acceptance evidence and rollback instructions. This is not yet public release approval.","files":[]},{"id":"B15","title":"Prepare and validate the four demo saves","legacy":[],"depends":["B14"],"goal":"Let Graham build meaningful examples only after the app's data path is stable.","steps":["Give Graham the companion save playbook. Use preserved working copies and verify slot/map/provider before every session; historical slot numbers are not automatic authorization to overwrite a save.","Work in the suggested order: base slot 4, isolated PF slot 3, RF/companions slot 19 and PF/companions slot 18.","For each feature prepare real game state, capture the in-game comparison and wait for a completed identity-matched export. Never populate fake values in JSON to make the showcase look successful.","Do not delete a working mixed pack because two mods sound related. Apply the documented version/configuration-specific ownership rules and use separate minimal profiles for independence testing.","Record acceptance for positive, legitimate empty, unavailable and stale states where appropriate. A visually busy 55-mod save is not proof all adapters work independently.","Publish only sanitized completed generations through the demo publisher, with capture manifest and feature checklist. Keep personal raw exports/screenshots private if they contain identifying data.","When Graham reports a discrepancy, tie it to candidate, source, save, farm, entity and generation before fixing. Retest affected automated and installed cases; refresh only the affected demo capture."],"tests":["DEMO01: All four snapshots have actual featured values, provider labels and correct farm scope.","DEMO02: Game, export and dashboard agree on representative fields/loans/storage/livestock/production.","DEMO03: No original user save is destroyed by preparation.","DEMO04: Public demos are sanitized, immutable, read-only and independent."],"output":"Four approved showcase captures and user-facing feature checklists. Gameplay preparation is Graham's later step, not a prerequisite for source repair.","files":[]},{"id":"B16","title":"Close every finding and deliver the release decision","legacy":["W10"],"depends":["B15"],"goal":"Make the support claims and release decision match exact tested artifacts.","steps":["Close F01-F14 individually with owning code changes, a real regression, package identity and installed/live proof where applicable.","Finalize the entire compatibility ledger, all catalog corrections, true dependency/mode edges, minimum-set/combination evidence and all 31 recommendation dispositions.","List any optional work explicitly deferred by Graham and remove premature live-support claims. An upstream limitation must be precise, source-backed and restricted to the affected feature.","Complete the existing protected-functionality/parity checklist and attach the four demo manifests. Re-capture any demo invalidated by final data-contract changes.","Provide one release candidate identity, artifact paths/hashes, exact passed scenarios, honest remaining risks, rollback and support instructions.","Keep signing as an explicitly documented distribution caveat unless Graham chooses a separate solution; do not imply an unsigned installer is signed or universally trusted, and do not instruct users to disable security protections.","Do not publish automatically. Ask for the release decision only after the required gates pass and provide a concise factual summary rather than another unresolved implementation plan."],"tests":["DONE01: No finding is closed solely because a code change exists.","DONE02: No skipped/blocked/live-unverified item is recorded as PASS.","DONE03: Public feature descriptions match tested capabilities and deployment modes.","DONE04: Final candidate has no undocumented byte changes since acceptance."],"output":"Completed build brief ledger, release recommendation and a single reproducible delivery package.","files":[]}],"gates":[{"id":"G0","title":"Baseline reconciled","phase":"B00","pass":"Exact changed-source versus installed identity, backups, ownership and evidence ledger are established."},{"id":"G1","title":"Exporter recovered","phase":"B01","pass":"Root cause identified; completed generations observed; same-process reload, teardown and diagnostics-off failures behave correctly."},{"id":"G2","title":"Data/config contracts safe","phase":"B02-B07","pass":"Settings preservation/no-write, active-only detection, namespace isolation, provider semantics, retention and units pass production-path regressions."},{"id":"G3","title":"Advertised integrations truthful","phase":"B08-B10","pass":"Every advertised live capability has meaningful source-backed data; all recommendations have an honest disposition and no hidden dependencies."},{"id":"G4","title":"Cross-layer proof complete","phase":"B11","pass":"Required source suites, transitions, minimum sets, constrained combinations, performance and security acceptance pass for the chosen scope."},{"id":"G5","title":"Public demo boundary safe","phase":"B12","pass":"Recorded demos use the real renderer, sanitized immutable data and enforced read-only independent source contexts."},{"id":"G6","title":"Candidate identifiable","phase":"B13","pass":"One V5 candidate, canonical ZIP and coherent final manifest; packaged and launched contents agree."},{"id":"G7","title":"Ready for Graham to prepare saves","phase":"B14","pass":"Fresh install, uninstall/reinstall, upgrade, setup, image conversion, native workflows and relevant installed/live routes pass."},{"id":"G8","title":"Showcases approved","phase":"B15","pass":"Four meaningful, correctly scoped, same-save comparisons are captured and sanitized; public demos remain independently usable."},{"id":"G9","title":"Release decision supported","phase":"B16","pass":"F01-F14 closure, compatibility claims, final artifact identity, rollback and all required evidence align. Publication still requires a release decision."}],"adapters":[{"key":"A01","title":"Enhanced Loan System","priority":"Finish first","kind":"Existing adapter repair","value":"Per-farm outstanding principal, monthly payment, interest, remaining term and collateral headroom where the verified loan manager exposes it.","source":"src/ELS_loanManager.lua and src/ELS_loan.lua; the mod owns an annuity-loan model separate from vanilla debt.","caveat":"Do not require another finance mod or substitute vanilla/all-farm debt for an unavailable ELS record.","version":"1.0.0.0","mp":"true","dependencies":[]},{"key":"A02","title":"Restricted Periods","priority":"Finish first","kind":"Existing adapter repair","value":"An actionable spreading calendar: slurry/digestate/manure permitted or blocked now, with reason and the next applicable window.","source":"scr/RestrictedPeriods.lua:34 SlurryBan.isBanActive(category), with separate liquid/solid rules and temperature handling.","caveat":"Calendar period numbers must follow the source; an unread API is unknown, not spreading allowed. No dependency on RF or RCC is declared.","version":"1.0.0.0","mp":"true","dependencies":[]},{"key":"A03","title":"Regional Crop Calendar","priority":"Finish first","kind":"Existing adapter repair","value":"Selected region, planting and harvesting windows by actual crop, and optional weather/yield modifiers with source labels.","source":"src/RegionManager.lua, CalendarService.lua, WeatherService.lua and YieldService.lua; selectedRegion and optional toggles are distinct.","caveat":"Custom-map crops may retain map calendars. RCC weather/yield features can overlap other providers; calendar-only use is not the same as enabling all toggles.","version":"1.1.0.2","mp":"true","dependencies":[]},{"key":"A04","title":"RealSilo - Realistic Silo Compartments","priority":"Finish first","kind":"Presence-only payload to real data","value":"Silo compartments, crop, litres/capacity, free space, active compartment and transfer progress.","source":"scripts/realSiloManager.lua getSilo/getTransfer; realSiloCompartmentStorage.lua getSlots/getActiveSlot; RealSiloUtil.getFarmIdForUid.","caveat":"Read all compartments without double-counting aggregated base storage. Vault version 1.0.0.0 differs from save manifest 1.1.0.2; pin the implementation target.","version":"1.0.0.0","mp":"true","dependencies":[]},{"key":"A05","title":"Storage Overhaul: Pallet Degradation System","priority":"Finish first","kind":"Presence-only payload to real data","value":"Pallet condition, sheltered/exposed state, temporary/permanent damage, value adjustment and at-risk goods.","source":"src/PalletMetadata.lua, PalletDegradationManager.lua and PalletPriceModifier.lua contain the owning condition/value logic.","caveat":"Read bounded cached metadata rather than raycasting every pallet again. Show stock only once; quality-adjusted valuation must not multiply the penalty twice.","version":"1.2.0.0","mp":"true","dependencies":[]},{"key":"A06","title":"Advanced Maintenance","priority":"Finish first","kind":"Fleet adapter","value":"Maintenance condition, start/breakdown restriction and service urgency on each relevant vehicle/tool.","source":"src/advancedmaintenance.lua and registration script define a distinct maintenance specialisation.","caveat":"Keep this adapter independent of EVM, Realistic Vehicle Service and ADS. Basic damage/fuel remains available without any maintenance mod.","version":"1.0.2.0","mp":"true","dependencies":[]},{"key":"A07","title":"Extended Vehicle Maintenance","priority":"Later alternative","kind":"Fleet adapter","value":"Service overdue status, fault type, chosen service route, unavailable-machine state and remaining service time where exposed.","source":"scripts/ExtendedVehicleMaintenance.lua and EVMServiceDialog.lua include maintenance, service, collision and fault logic.","caveat":"It already includes collision damage and puncture-style faults. Combining separate mods for the same behaviour is a risk requiring evidence, not an automatic supported preset.","version":"1.0.0.0","mp":"true","dependencies":[]},{"key":"A08","title":"Realistic Vehicle Service","priority":"Later alternative","kind":"Fleet adapter","value":"Faults, warm-up/availability and recovery/workshop status as read-only fleet details.","source":"scripts/core/FaultSystem.lua and scripts/specs/BreakdownSpec.lua/ImmobilizerSpec.lua.","caveat":"Never invoke towing, repair or key actions just to read status. Coexistence with other start/fault systems needs targeted tests.","version":"1.0.0.0","mp":"true","dependencies":[]},{"key":"A09","title":"Seasonal Milk Production","priority":"Finish first","kind":"Presence-only payload to real data","value":"Current seasonal milk modifier, phase/next peak and any available health factor beside actual output.","source":"scripts/SeasonalMilkProduction.lua:getSeasonalModifier and getHealthModifier.","caveat":"A modifier is not realised milk output or guaranteed forecast. Preserve distinctions between this mod, DairyCore and Ritter data.","version":"1.0.0.1","mp":"true","dependencies":[]},{"key":"A10","title":"Seasonal Wool Production","priority":"High-value addition","kind":"Seasonal livestock","value":"Next shearing, accumulation period, health effects and expected fee where source data supports it.","source":"scripts/SeasonalWoolAdapter.lua includes distinct vanilla and Realistic Livestock reads; SeasonalWoolProduction.lua owns period state.","caveat":"This source explicitly accommodates Ritter rather than requiring it. Verify live ownership and accumulated values, not only settings.","version":"1.0.0.2","mp":"true","dependencies":[]},{"key":"A11","title":"Imperial System Conversion Settings","priority":"Finish first","kind":"Display compatibility","value":"Follow the active mod's chosen liquid/crop/mass/measurement settings across existing screens.","source":"scripts/UnitConversionManager.lua, UnitConversionData.lua and UnitConversionOverrides.lua.","caveat":"Display-only; this is not an excuse to change prices or inventory arithmetic. Saved profile files cannot activate an inactive mod.","version":"1.1.0.0","mp":"true","dependencies":[]},{"key":"A12","title":"Save Unit Profiles","priority":"Finish first","kind":"Display compatibility","value":"Show the selected save's currency and supported unit profile consistently.","source":"scripts/SU_Core.lua; regional profile selection is separate from the Imperial fill conversion mod.","caveat":"Per-save/profile/client context must be explicit. Do not require Imperial or British Fill Units.","version":"1.2.0.2","mp":"true","dependencies":[]},{"key":"A13","title":"Livestock Monitor","priority":"Finish first","kind":"Useful enrichment plus native coverage","value":"Barn warnings, alert state and supported settings alongside the dashboard's own food/water/health data.","source":"scripts/LivestockMonitor.lua, LivestockMonitorAlerts.lua and settings code.","caveat":"The current dashboard reader covers alert/settings fields, not the full detailed barn data described by the catalog. Native livestock monitoring must not require this mod.","version":"1.0.0.0","mp":"true","dependencies":[]},{"key":"A14","title":"Production Watcher","priority":"Finish first","kind":"Useful enrichment plus native coverage","value":"Input shortage and output blockage warnings with production context.","source":"scripts/ProductionWatcher.lua; the mod has low-input/high-output alert rules.","caveat":"Native production levels and useful warnings must work without Production Watcher. Do not call a summary of alert objects complete production integration.","version":"1.0.0.0","mp":"true","dependencies":[]},{"key":"A15","title":"Production Schedule","priority":"High-value addition","kind":"Production planning","value":"Per-recipe active-month calendar and the reason a production is intentionally paused.","source":"Scripts/ProductionSchedule.lua stores self.data by point/recipe, with months/status and owned-production helpers.","caveat":"Do not describe planned seasonal shutdown as a breakdown. Other scheduling controllers may compete for the same recipe state.","version":"1.1.0.0","mp":"true","dependencies":[]},{"key":"A16","title":"Economic History","priority":"High-value addition","kind":"Finance history","value":"Farm-scoped historical income/cost categories, trends and loan/balance history, clearly dating the recorded coverage.","source":"src/EconomicHistoryDataCollect.lua FinancialLogger history/current-finance functions and persistent month/farm records.","caveat":"Do not invent history before installation or expose another farm's restricted ledger. Prefer a bounded adapter over arbitrary-path CSV scraping.","version":"1.0.0.1","mp":"true","dependencies":[]},{"key":"A17","title":"Task List","priority":"High-value addition","kind":"Read-only work planner","value":"Due and upcoming tasks, priorities, recurrence, effort and field/group links.","source":"main.lua contains activeTasks/taskGroups and getActiveTasksForCurrentFarm/getTasksForNextYear.","caveat":"The current-farm helper depends on playerUserId; a dedicated exporter needs explicit farm scoping, not a fake player. Do not add remote task mutation in this first scope.","version":"1.2.0.1","mp":"true","dependencies":[]},{"key":"A18","title":"Animal Food Calculator","priority":"High-value enrichment","kind":"Feeding and production rates","value":"Active reference/scaling mode and correctly adjusted feed, water, straw and supported production rates.","source":"AFCConsumptionScaling.lua:getScaleFactor plus reference manager and actual animal data.","caveat":"AFC can change simulation rates, not just display them. Do not multiply already-scaled live consumption again or assume universal animal-system compatibility.","version":"1.1.0.2","mp":"true","dependencies":[]},{"key":"A19","title":"Animal Planner","priority":"High-value addition","kind":"Livestock planning","value":"Current and full-capacity consumption/output, feed-cost estimates, herd value growth and supported logistics mode.","source":"scripts/AnimalPlannerData.lua:getHusbandryData; admin/logistics modules expose separate capabilities.","caveat":"First release should be read-only. Its logistics/admin features can change behaviour/capacity, so do not silently combine competing distribution controllers.","version":"1.0.0.0","mp":"true","dependencies":[]},{"key":"A20","title":"Field Profitability Ledger","priority":"High-value addition","kind":"Field economics, SP-limited","value":"Per-field/crop-cycle costs, crop value, margin, yield and data-quality confidence.","source":"src/services/ReportService.lua and the ledger/export/runtime modules separate reported totals, quality and live/canonical data.","caveat":"The vault descriptor declares multiplayer unsupported. Do not advertise dedicated-server coverage or equate projected crop value with actual sale revenue.","version":"1.0.0.0","mp":"false","dependencies":[]},{"key":"A21","title":"VIP Order Manager","priority":"High-value addition","kind":"Orders, SP-limited","value":"Current VIP order, deliveries remaining, destination, reward and upcoming orders.","source":"VIPOrderManager.lua and gui/OrderFrame.lua expose order quantities, delivered fill levels, payout and destination.","caveat":"The reviewed version and official listing do not support multiplayer. Read-only progress, not automatic delivery/cancellation.","version":"1.2.1.0","mp":"false","dependencies":[]},{"key":"A22","title":"Farm Reputation","priority":"Useful later","kind":"Contracts with genuine dependency","value":"Farm/contractor reputation, rank progress, limits, evaluation and unlocked opportunities.","source":"scripts/ReputationManager.lua stores reputationByFarm/contractorDataByFarm; AKF evaluation readers provide the breakdown.","caveat":"Requires Better Contracts by descriptor and official listing. That is a real upstream dependency; our other adapters must not inherit it.","version":"1.1.0.0","mp":"true","dependencies":"FS25_BetterContracts"},{"key":"A23","title":"Yield Tracker","priority":"Useful later","kind":"Harvest history, SP-limited","value":"Field/year/crop yield trends where the mod has actual captured harvest history.","source":"scripts/yieldTracker.lua and trackedCropTypes.lua.","caveat":"The reviewed package is single-player-only and enumerates supported fill types; do not promise every Montana multifruit crop.","version":"1.0.0.2","mp":"false","dependencies":[]},{"key":"A24","title":"Moisture System","priority":"Useful later","kind":"Moisture and quality provider","value":"Available crop/material moisture, quality and storage/harvest warnings.","source":"The package has dedicated moisture/quality runtime code rather than only a visual HUD.","caveat":"Feasible candidate, not a certified adapter. Review exact ownership and compatibility against RF crop stress, Realistic Weather and other drying mods before adopting a combined preset.","version":"2.0.0.3","mp":"true","dependencies":[]},{"key":"A25","title":"Silage Compaction Monitor","priority":"Prefer native first","kind":"Silage planning","value":"Bunker fill and compaction, plus a clearly labelled equipment-dependent time estimate where available.","source":"Compaction_Monitor.lua reads bunker and vehicle/implement mass context.","caveat":"Core bunker progress should not require this HUD mod. Its current-vehicle estimate is not necessarily available on an unattended dedicated server.","version":"1.1.0.0","mp":"true","dependencies":[]},{"key":"A26","title":"Field Leasing","priority":"Useful later","kind":"Land tenure","value":"Leased fields, monthly payments, minimum term and termination eligibility.","source":"Field Leasing's agreement/manager source records rental contracts separately from simple land ownership.","caveat":"Distinct from renting your own land out and multiplayer marketplace deals. Never label leased land as permanently owned.","version":"1.0.0.1","mp":"true","dependencies":[]},{"key":"A27","title":"Rent Your Field","priority":"Useful later","kind":"Land income","value":"Fields rented out, rent income, minimum duration and early-termination liability.","source":"src/RentAgreement.lua and RentYourFieldManager.lua.","caveat":"Owner and operator can differ. A generic farm-ownership filter must not pretend rented-out land is currently worked by the player.","version":"1.0.0.1","mp":"true","dependencies":[]},{"key":"A28","title":"Farmland Marketplace","priority":"Useful later","kind":"Multiplayer land business","value":"Pending offers, accepted sale/lease agreements, owner/operator and farm-specific obligations.","source":"Package is explicitly multiplayer-only; offer/acceptance changes land use and money.","caveat":"Needs a real multi-farm multiplayer demonstration, not either single-player Montana save.","version":"1.0.4.0","mp":"true","dependencies":[]},{"key":"A29","title":"Distribution Redux","priority":"Later complex integration","kind":"Production logistics","value":"Distribution modes, sources/destinations, effective demand and available transfer statistics.","source":"SmartDistribution.lua getAssetMode/getAssetSellTiming and distribution stats/events.","caveat":"Only export available observed state, not invented routes. Test with RealSilo, Animal Planner and other distribution modifiers; start read-only.","version":"1.0.0.1","mp":"true","dependencies":[]},{"key":"A30","title":"Factory Profit Calculator","priority":"Finish catalog coverage","kind":"Production economics","value":"Effective recipes/cycles/capacities and clearly labelled expected margin at current prices.","source":"Factory Profit Calculator includes a calculator and an administrator recipe/capacity editor.","caveat":"Read modified live recipes, not original XML, and distinguish expected from realised profit. Do not export admin write controls publicly.","version":"1.0.0.1","mp":"true","dependencies":[]},{"key":"A31","title":"Farm Operations Dashboard","priority":"Prefer native first","kind":"Operations overview","value":"A unified what-needs-attention board across existing fields, animals, production, fleet and markets.","source":"FarmOperationsDashboard.lua is another view over much of the same native game state.","caveat":"Do not make our basic dashboard depend on another dashboard. Learn the useful product requirements without copying implementation or creating two competing totals.","version":"1.1.0.0","mp":"true","dependencies":[]}],"saves":[{"slot":4,"id":"base","name":"Riverbend Base","provider":"Base game, Farm Dashboard only","baseline":"Earlier manifest contained only Farm Dashboard, ten farm-1 vehicles, three Angus cows at zero health and no owned production point. This is a captured baseline, not a fresh check or a recommendation to keep animals unhealthy.","purpose":"Prove the dashboard is useful without PF, RF or any companion. Establish the reference for every optional integration.","prepare":["Load the preserved base demo copy and keep all optional companion packages inactive for this scenario. Mods may remain installed on disk so inactive-detection behavior is also exercised.","Choose owned fields that genuinely illustrate contrasting fertiliser and lime requirements. If those states already exist, preserve them; otherwise create only the necessary state through normal game actions.","Prepare one ordinary healthy vehicle and one controlled low-fuel or service-needed example. Avoid leaving every machine empty or damaged.","Supply the small animal group appropriately and allow the game to reflect healthy husbandry. A single clearly identified low-resource example can demonstrate an alert; do not use an entirely neglected farm as the product baseline.","Set up one simple production with real inputs and visible operation. Include some stored crop and, where convenient, bales so stock totals are meaningful.","Record a representative farm finance figure and verify native fields, animals, production, stock and fleet all render without Livestock Monitor or Production Watcher."],"compare":["Vanilla fertiliser/lime text matches the same in-game field; no PF nitrogen/pH bars or RF-only values appear as active.","Low-fuel filtering selects the intended vehicle and leaves the healthy example out.","Animal counts/feed and production input/output agree with the game. Stored crops and bales are not duplicated.","Companion presence is empty/inactive despite unrelated ZIPs installed on disk. Display units follow the intended base preference.","A valid farm with no assets remains selected if intentionally chosen."],"capture":["Fields and soil native view with two distinct real states.","Fleet low-fuel/service example and a normal vehicle.","Healthy livestock plus one meaningful production and stock view.","An explicit recorded-demo/base-only identity and the completed capture timestamp."],"avoid":"Do not add PF or a companion merely to make a native page populate. If native data is missing, return that defect to Ash."},{"slot":3,"id":"precision-farming","name":"Riverbend Precision Farming","provider":"Farm Dashboard plus Precision Farming only","baseline":"Earlier manifest contained only Farm Dashboard and PF, nine farm-1 vehicles, three zero-health Angus cows and no owned production point. PF XML/files existed, but purchased scan coverage and correctly rendered measurements were not proven.","purpose":"Show exactly what PF adds and prove unknown soil readings are not displayed as measured zero.","prepare":["Load the preserved PF demo copy. Keep RF soil and unrelated companions off; maintain a comparable base layout where practical without overwriting the original careers.","Keep one genuinely unscanned field and one field with a valid purchased/available PF soil result. Use the game's supported sampling process; do not alter telemetry to simulate a scan.","Choose measured fields with useful nitrogen and pH differences. If a current measurement is unavailable but a target is known, keep that state as an intentional availability example.","Use normal fertilising/liming actions on a selected demonstration area where appropriate and capture the change after the provider and exporter update.","Include ordinary fleet, animals, production and storage activity so the demo is not just a soil screen; reuse the base checklist for those native areas.","Record the PF panel values and map/field identity at the same game time as the completed dashboard export."],"compare":["Unscanned/unknown is visibly different from an actual measured zero. Missing pH is not shown as pH zero.","Current and target nitrogen remain separate and labelled with the provider's actual units.","Field card, detail, overview and relevant map display agree about the same field.","No RF soil module or unrelated companion is shown as active.","After a genuine in-game soil change, a fresh completed generation updates the correct field without retaining old provider data."],"capture":["A scanned field with meaningful current/target readings.","An unscanned or otherwise honestly unavailable field.","A nitrogen/liming example compared to PF's own display.","PF identity plus native feature views and completed capture metadata."],"avoid":"Do not buy another scan to hide a collector failure. First distinguish genuine unsampled ground from a read/merge/UI defect."},{"slot":19,"id":"realistic-farming","name":"Montana RF and companions","provider":"RF-led rich showcase; exact active capabilities must be recorded","baseline":"Earlier manifest contained 55 mods and 23 farm-1 vehicles. ELS had settings but no loans. RealSilo held nine entries with no configured/filled compartments. RCC selected vanilla with weather/yield off. Ritter had separate animal records that cannot be counted as the selected farm's livestock without correct ownership mapping.","purpose":"Demonstrate useful RF and companion information, not simply a large list of detected mods.","prepare":["Have Ash review effective price ownership before this session: the captured pack included RF Fuel Costs with Realistic Diesel Price and RF Market Dynamics with Dynamic Market. Resolve only proven conflicting enabled features; do not indiscriminately delete working mods.","Create one sensible, identifiable ELS loan through the mod's actual UI in the demo copy. Record outstanding balance, repayment/interest details and the selected farm. Keep a separate debt-free farm if practical for scope testing.","Configure at least two RealSilo compartments and fill them with representative crops using supported game actions. Record capacity, quantity and active compartment; capture transfer progress only if actually occurring.","Select a real intended RCC region rather than vanilla for the calendar showcase. Keep optional weather/yield toggles in the reviewed safe configuration and record them, instead of turning everything on for display.","Choose a clear restriction state for slurry/digestate/manure. Capture actual category-specific allowed/blocked status and its reason. Do not advance an unprotected save merely to force a ban.","Supply and operate the intended animal system. With Ritter, select the correct farm and use its own animal ownership/source mapping; never infer zero animals solely from missing vanilla clusters.","Prepare a producing livestock example and real production inputs/outputs. If seasonal milk/wool or pallet degradation are featured, capture their genuine current factors/conditions without double-applying them.","Prepare an RF soil example with known provider data and a deliberate fleet service/stock example. Each feature card needs a real value, reason and useful interpretation."],"compare":["Selected-farm ELS totals and individual loans agree; a zero-loan farm never receives all-farm debt.","Compartment quantities reconcile with native storage once, not twice.","RCC region/calendar and spreading restrictions match the game; unknown state never becomes vanilla or allowed.","RF soil values come from the enabled RF provider and remain distinct from PF scales.","Ritter/vanilla animal ownership, effective seasonal output and production/storage totals agree without duplicated animals or rate multipliers.","The effective fuel/selling prices match the game's final values under the documented provider configuration."],"capture":["RF field/soil example.","A populated ELS loan and clearly scoped farm.","Filled silo compartments and actual region/calendar/restriction information.","Producing livestock/production and one fleet/condition example.","Exact mod/version/configuration manifest and explicit limitations."],"avoid":"This rich save does not prove any adapter is independent. Ash must retain separate minimum-set and combination tests."},{"slot":18,"id":"precision-companions","name":"Montana PF and companions","provider":"PF-led rich showcase with the intended unit and companion configuration","baseline":"Earlier manifest contained 33 mods and 23 farm-1 vehicles. Five farm-1 husbandries had no saved vanilla animal clusters. Vanilla debt was zero. Soil Work Yield Bonus had no worked-cell records. Owned production recipes were enabled without saved input stocks in their inspected blocks.","purpose":"Show PF alongside useful independent companions, with real examples of the features that were previously empty.","prepare":["Load the preserved PF-companion demo copy and confirm the intended unit mod/profile and PF provider are active. Do not activate RF Soil merely to make a soil panel appear.","Prepare PF sampled/unsampled and nitrogen/pH cases as in the isolated PF save, then retain the richer pack for combination behavior.","Populate and supply the intended supported animal system; verify its actual ownership model. Do not assume empty vanilla clusters prove no animals under every custom animal system.","Create a controlled vanilla debt example for I Need A Loan/Automatic Loan Repay if those are the chosen active policies. Record the balance and repayment event; do not substitute ELS debt into the vanilla-credit demo.","Work a real field with a supported implement so Soil Work Yield Bonus has actual recorded coverage. Capture the resulting state only when the adapter reads the mod's own data.","Supply enabled production recipes with real inputs and allow meaningful output. Add a service-due vehicle through normal supported play and, where featured, a genuine scheduling/logistics state.","Check Imperial/British/profile behavior against the intended active configuration. Keep native quantities canonical and compare real displayed units rather than changing underlying stored values.","Do not omit Livestock Monitor or Production Watcher merely because the RF showcase uses them. Their availability depends on supported capabilities, not demo-pack exclusivity."],"compare":["PF fields show correct measurements and no stale RF soil from the other save.","Vanilla debt/repayment is correctly scoped and distinguished from an ELS loan.","Worked-field coverage, recipe inputs/outputs and service state reflect actual game changes.","Livestock counts/needs and native totals remain correct with the chosen companion combination.","Units are consistent across storage, vehicle capacities and production; inactive unit settings from another save do not leak in."],"capture":["PF soil plus the intended units.","An actual debt/repayment example, not only a policy label.","Worked-field bonus coverage and real production stock.","Populated livestock and a service-needed machine.","Completed snapshot identity, feature list and source versions."],"avoid":"Zero debt, empty barns and enabled-but-unsupplied factories are valid game states, but they cannot serve as evidence of populated live integration features."}],"findings":[{"id":"F01","title":"The current save export is still an empty bootstrap, not a working live feed","status":"Ash reports partial implementation; independent source/installed/lifecycle acceptance outstanding","repair":"Instrument one bounded diagnostic run at the actual update/collector/write boundaries, identify the first stage not progressing, and repair that stage. Keep errors visible independently of verbose tracing. Do not declare the grace-clock change the sole fix without observing a completed live export.","phase":"B01, B03, B14"},{"id":"F02","title":"Mission lifecycle initialization is unwired and updates are registered twice","status":"Ash reports partial implementation; independent source/installed/lifecycle acceptance outstanding","repair":"Use one supported mission-start subscription and one updater registration, both idempotent. Reset session-owned state on teardown. Verify callback arguments and load order against the current game source before implementation.","phase":"B01"},{"id":"F03","title":"The original XML parsing bug still turns unrelated Settings saves into module changes","status":"Ash reports partial implementation; independent source/installed/lifecycle acceptance outstanding","repair":"Parse exact attributes of exact elements with the existing XML dependency. Separate dirty states for UI, server, mod and LAN domains. Preserve unknown XML attributes and use a preserving read-modify-write transaction. Migrations must not override intentional current settings on every load.","phase":"B02, B14"},{"id":"F04","title":"Installed mods are being mistaken for active mods","status":"Original audit finding; not independently reassessed after the reported repairs","repair":"Establish active mission membership first. Use the inventory only to resolve metadata for that active name. Gate settings-file fallbacks behind active membership. Support aliases explicitly; do not use an unrestricted installed-name scan to create active detections.","phase":"B04, B07, B11"},{"id":"F05","title":"Several companion readers look in the wrong Lua environment","status":"Original audit finding; not independently reassessed after the reported repairs","repair":"Create a source-backed adapter registry with active name, environment/mission handle, supported version, capability probe, reader and scope for each supported integration. Resolve companion-owned symbols through the owning environment or documented mission handle, never by flattening all mods into one global namespace.","phase":"B04, B09"},{"id":"F06","title":"Unavailable companion data is displayed as reassuring factual data","status":"Original audit finding; not independently reassessed after the reported repairs","repair":"Represent detected, ready, unavailable, failed and stale separately. Only show allowed/zero/default values after a successful complete read with those actual values. Make unavailable reasons and source timestamps visible without alarming normal absent-mod users.","phase":"B03, B08, B09"},{"id":"F07","title":"The selected farm can be shown another farm's enhanced-loan totals","status":"Original audit finding; not independently reassessed after the reported repairs","repair":"Keep selected-farm and all-farms views separate. Preserve zero with explicit availability/completeness, not truthiness. Preserve a valid user-selected farm even when it owns no equipment or fields; infer only when selection is absent or invalid.","phase":"B03, B08, B11"},{"id":"F08","title":"Snapshot retention resurrects empty/disabled sections and is not session-safe","status":"Original audit finding; not independently reassessed after the reported repairs","repair":"Replace non-empty heuristics with section outcome and provenance. Carry forward only omitted/pending/failed data from the same save identity. Successful empty and explicit disabled must invalidate backup and persisted snapshot state. Keep offline last-good data, but label it and scope it correctly.","phase":"B03, B06"},{"id":"F09","title":"The merge immediately removes the freshness markers it just added","status":"Original audit finding; not independently reassessed after the reported repairs","repair":"Separate transport freshness, export generation and per-section freshness. A successful vehicle update may clear a vehicle error, not retained soil/stock/companion provenance. Retain source timestamps through persistence and rendering.","phase":"B03, B06"},{"id":"F10","title":"Soil bars still conflate missing current measurements with measured zero","status":"Original audit finding; not independently reassessed after the reported repairs","repair":"Resolve soil provider and measurement availability explicitly: vanilla application levels, PF N/pH or RF nutrients/pH. Targets, current values and scan status must be independent. Do not turn an unknown current value into zero or request another soil scan solely because telemetry failed.","phase":"B05, B07"},{"id":"F11","title":"One companion reader failure can erase the entire companion payload","status":"Original audit finding; not independently reassessed after the reported repairs","repair":"Isolate each adapter and preserve independent results. Cache mission activation, retry readiness at a bounded cadence, and budget expensive scans. Record duration, row truncation and failure reason per adapter.","phase":"B01, B04, B11"},{"id":"F12","title":"Build identity and the test configuration are too ambiguous to prove a repair","status":"Original audit finding; not independently reassessed after the reported repairs","repair":"Use one deliberate candidate with coherent version/build identifiers and canonical ZIP naming. Separate source, package, installed and live-save evidence. Retire the loose release-test copy by reversible backup only after consent and when the game is closed. Do not recreate or wipe demo saves as a debugging substitute.","phase":"B00, B13, B14, B16"},{"id":"F13","title":"Malformed-existing configuration recovery is approved by the current regression test","status":"Confirmed in inspected test; caller write protection not independently verified","repair":"Reject malformed-present configuration and prove the existing file is unchanged; reserve default creation for a truly missing file.","phase":"B02, B11"},{"id":"F14","title":"Field extraction test duplicates helpers rather than calling production code","status":"Confirmed in inspected test; a proof gap rather than a newly demonstrated runtime failure","repair":"Exercise the real collector/parser and the real merge-to-selector path; do not certify copied fixture logic.","phase":"B05, B11"}]};


export default function CompleteBuildOrder() {
  const theme = useHostTheme();
  const dispatch = useCanvasAction();
  const [view, setView] = useState("order");
  const [query, setQuery] = useState("");
  const [saveId, setSaveId] = useState("base");
  const openFile = (path: string) => dispatch({ type: "openFile", path });
  const list = (items: string[], ordered = false) => ordered
    ? <ol style={{paddingLeft: 22, lineHeight: 1.7}}>{items.map((x,i)=><li key={i} style={{marginBottom: 8}}>{x}</li>)}</ol>
    : <ul style={{paddingLeft: 22, lineHeight: 1.7}}>{items.map((x,i)=><li key={i} style={{marginBottom: 8}}>{x}</li>)}</ul>;
  const matched = (value: string) => value.toLowerCase().includes(query.toLowerCase());
  const phases = brief.phases.filter(p=>matched([p.id,p.title,p.goal,...p.steps,...p.tests].join(" ")));
  const adapters = brief.adapters.filter(a=>matched([a.key,a.title,a.priority,a.value,a.caveat].join(" ")));
  const selectedSave = brief.saves.find(s=>s.id===saveId) || brief.saves[0];
  const border = "1px solid " + theme.stroke.tertiary;
  return <Stack gap={18} style={{maxWidth: 1120, margin: "0 auto", padding: 22, color: theme.text.primary}}>
    <Text size="small" tone="secondary">FARM DASHBOARD V5 / IMPLEMENTATION HANDOFF / 23 SEPTEMBER 2026</Text>
    <H1 style={{fontSize: 26}}>One complete build order</H1>
    <Text>Repair the source of incorrect data, prove independent mod support, deliver one identifiable installed candidate, then prepare and publish meaningful demo saves.</Text>
    <Callout tone="warning" title="Plan, not a passing test report">
      Ash reports partial W01/W02 changes. They must be reconciled and preserved where correct.
      No phase or release gate is marked passed here, and no product code, installer or save is changed by this artifact.
    </Callout>
    <Row wrap gap={8}>
      <Pill>17 build stages</Pill><Pill>14 findings</Pill><Pill>31 recommendations</Pill><Pill>4 demo saves</Pill><Pill>10 evidence gates</Pill>
    </Row>
    <Row wrap gap={8}>
      <Button onClick={()=>openFile(brief.mainPath)}>Open full engineering brief</Button>
      <Button variant="secondary" onClick={()=>openFile(brief.savePath)}>Open Graham's save guide</Button>
    </Row>
    <Divider />
    <Row wrap gap={8}>
      {[["order","Build order"],["integrations","Integration backlog"],["saves","Save preparation"],["gates","Evidence gates"],["findings","Finding closure"]].map(([id,label])=>
        <Pill key={id} active={view===id} onClick={()=>setView(id)}>{label}</Pill>)}
    </Row>
    {(view==="order" || view==="integrations") && <input aria-label="Search build steps and integrations"
      value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search a finding, mod, step or acceptance case"
      style={{font:"inherit",padding:"8px 10px",width:"100%",boxSizing:"border-box",color:theme.text.primary,background:theme.bg.editor,border:"1px solid "+theme.stroke.secondary,borderRadius:4}} />}

    {view==="order" && <Stack gap={16}>
      <H2>Build first. Prepare saves after installed acceptance.</H2>
      <Text tone="secondary">B00-B16 is the controlling order. W identifiers preserve traceability to the earlier plan, not a second queue. Shared schema/store changes have one coordinated owner.</Text>
      <Callout tone="info" title="Two different finish lines">
        G7 means the exact installed app is ready for Graham to prepare saves.
        G9 means implementation, compatibility evidence, approved demo captures and final artifact identity support a release decision.
      </Callout>
      <Text size="small" tone="secondary">{phases.length} matching build stages</Text>
      {phases.map(p=><details key={p.id} style={{borderBottom:border,paddingBottom:14}}>
        <summary style={{cursor:"pointer",lineHeight:1.6}}>
          <strong>{p.id + ". " + p.title}</strong>
        </summary>
        <Stack gap={9} style={{paddingTop:12}}>
          <Text weight="semibold">{p.goal}</Text>
          <Text size="small" tone="secondary">Entry: {p.depends.join(", ") || "Start"}; previous plan: {p.legacy.join(", ") || "Consolidated additional work"}. Status: planned, not accepted.</Text>
          <H3>Implementation sequence</H3>{list(p.steps,true)}
          <H3>Required acceptance</H3>{list(p.tests)}
          <H3>Deliverable</H3><Text>{p.output}</Text>
        </Stack>
      </details>)}
      {phases.length===0 && <Text>No matching stages. Clear the search to see the full build order.</Text>}
    </Stack>}

    {view==="integrations" && <Stack gap={16}>
      <H2>Finish honest data, then expand in controlled waves</H2>
      <Text>Each adapter needs a pinned source/version, active-only detection, correct namespace, independent error handling, farm scope, real data and minimum-set proof. A ModHub ID is not a runtime Lua namespace.</Text>
      <Callout tone="info" title="No artificial dependencies">
        Native features work without companions. Only real upstream prerequisites constrain an adapter.
        The full brief also covers all existing advertised catalog entries, ten catalog corrections and twelve shared-provider/conflict families.
      </Callout>
      <Text size="small" tone="secondary">{adapters.length} matching recommendation records. Source feasibility is not implementation or live acceptance.</Text>
      {adapters.map(a=><details key={a.key} style={{borderBottom:border,paddingBottom:12}}>
        <summary style={{cursor:"pointer",lineHeight:1.6}}><strong>{a.key + ". " + a.title}</strong>{" / "}{a.priority}</summary>
        <Stack gap={9} style={{paddingTop:10}}>
          <Text>{a.value}</Text>
          <Text size="small" tone="secondary">{a.kind}; reviewed version {a.version || "see source manifest"}; descriptor multiplayer flag {String(a.mp)}.</Text>
          <H3>Source starting point</H3><Text>{a.source}</Text>
          <H3>Constraint</H3><Text>{a.caveat}</Text>
          <Text size="small" tone="secondary">Required prerequisites from reviewed descriptor: {Array.isArray(a.dependencies) ? (a.dependencies.join(", ") || "none declared; runtime independence still requires proof") : String(a.dependencies)}.</Text>
        </Stack>
      </details>)}
      {adapters.length===0 && <Text>No matching integrations. Clear the search to restore the full backlog.</Text>}
    </Stack>}

    {view==="saves" && <Stack gap={16}>
      <H2>Graham's later gameplay checklist</H2>
      <Callout tone="warning" title="Wait for G7 and use preserved working copies">
        The slot numbers are from the captured audit, not instructions to overwrite a personal save.
        Ash supplies a tested installed candidate and safe capture/publication process first.
      </Callout>
      <Row wrap gap={8}>{brief.saves.map(s=><Pill key={s.id} active={saveId===s.id} onClick={()=>setSaveId(s.id)}>{"Slot " + s.slot + ": " + s.name}</Pill>)}</Row>
      <H3>{selectedSave.name}</H3><Text>{selectedSave.purpose}</Text>
      <Text size="small" tone="secondary">Provider: {selectedSave.provider}</Text>
      <details><summary style={{cursor:"pointer"}}>What the earlier audit found</summary><Text>{selectedSave.baseline}</Text></details>
      <H3>Prepare through normal game actions</H3>{list(selectedSave.prepare,true)}
      <H3>Compare the same game state and completed export</H3>{list(selectedSave.compare,true)}
      <H3>Capture for the recorded demo</H3>{list(selectedSave.capture)}
      <Callout tone="info" title="Important limit">{selectedSave.avoid}</Callout>
    </Stack>}

    {view==="gates" && <Stack gap={16}>
      <H2>Evidence required before calling it complete</H2>
      <Text>Source-tested, package-tested, installed-tested and lifecycle-tested are separate evidence states. Passing a helper test, generating a file or showing a startup log does not satisfy later gates.</Text>
      {brief.gates.map(g=><section key={g.id} style={{borderBottom:border,paddingBottom:14}}>
        <Row wrap gap={8}><Pill>{g.id}</Pill><Text size="small" tone="secondary">{g.phase} / NOT TESTED in this planning task</Text></Row>
        <H3>{g.title}</H3><Text>{g.pass}</Text>
      </section>)}
      <Callout tone="warning" title="Do not reset data to hide a regression">
        Preserve evidence and repair the owning path. Any change to accepted packaged bytes requires an identifiable candidate and affected re-testing.
        Public V4, canonical ZIP naming, shared converter ownership and existing working functionality remain protected.
      </Callout>
    </Stack>}

    {view==="findings" && <Stack gap={16}>
      <H2>All fourteen findings have an owning build stage</H2>
      <Text tone="secondary">Original findings are captured audit evidence. The newly reported implementation is not independently certified here.</Text>
      {brief.findings.map(f=><section key={f.id} style={{borderBottom:border,paddingBottom:14}}>
        <Row wrap gap={8}><Pill>{f.id}</Pill><Text size="small" tone="secondary">{f.phase}</Text></Row>
        <H3>{f.title}</H3><Text>{f.repair}</Text><Text size="small" tone="secondary">{f.status}</Text>
      </section>)}
    </Stack>}
    <Divider />
    <Text size="small" tone="secondary">Use the full engineering brief for exact file ownership, proposed contracts, command entry points, per-adapter recipe, test cases, rollout/rollback and final handoff templates. This view never launches tests, installs software or publishes a release.</Text>
  </Stack>;
}
